":root { --tela-fundo: #f8f8f8; --tela-borda: #dee2e6; --tela-texto: #333; --tela-azul: #1351b4; }
body { background-color: var(--tela-fundo); color: var(--tela-texto); margin: 0px; font-family: Rawline, Raleway, sans-serif; }
.atalho-conteudo { z-index: 10; }
.barra-superior { border-bottom: 1px solid var(--tela-borda); background-color: rgb(255, 255, 255); align-items: center; padding: 8px 16px; display: flex; }
.marca-govbr { color: var(--tela-azul); font-size: 24px; font-weight: 700; text-decoration: none; }
.trilha-servico { max-width: 960px; margin: 0px auto; padding: 8px 16px 0px; }
.area-solicitacao { max-width: 960px; margin: 0px auto; padding: 16px; }
.titulo-solicitacao { margin: 8px 0px; font-size: 32px; font-weight: 600; }
.apoio-solicitacao { margin: 0px 0px 24px; }
.formulario-solicitacao { border: 1px solid var(--tela-borda); background-color: rgb(255, 255, 255); padding: 24px; }
.retorno-envio:not(:empty) { margin-bottom: 24px; }
.linha-campos { flex-wrap: wrap; gap: 24px; display: flex; }
.linha-campos .campo { flex: 1 1 280px; }
.campo { border: 0px; min-width: 0px; margin: 0px 0px 24px; padding: 0px; }
.campo-nome { max-width: 560px; }
.campo-cpf { max-width: 280px; }
.campo-servico .br-input input:focus, .campo-servico .br-input input:focus-visible, .campo-unidade .br-input input:focus, .campo-unidade .br-input input:focus-visible { box-shadow: none; outline: none; border-color: var(--border-color-alternative) !important; }
.grupo-forma legend, .grupo-recursos legend { margin-bottom: 8px; padding: 0px; font-size: 14px; font-weight: 600; }
.grupo-forma .br-radio, .grupo-recursos .br-checkbox { margin-bottom: 8px; }
.campo-data { max-width: 280px; }
.campo-descricao textarea { width: 100%; }
.campo-declaracao { border-top: 1px solid var(--tela-borda); padding-top: 8px; }
.campo-declaracao .feedback { margin-top: 8px; display: inline-block; }
.acoes-formulario { justify-content: flex-end; gap: 16px; display: flex; }
.acao-cancelar, .acao-enviar { min-width: 120px; }
.historico { margin-top: 40px; }
.titulo-historico { margin: 0px 0px 16px; font-size: 24px; font-weight: 600; }
.tabela-anteriores table { width: 100%; }
.paginacao-anteriores { justify-content: center; align-items: center; gap: 8px; padding: 8px 0px; display: flex; }
.dialogo-descarte { color: rgb(51, 67, 51); }
.acao-manter, .acao-descartar { min-width: 120px; }"
